    // Editor language -> one of the string tables
    ElixirAI.langOf = function (l) {
        l = String(l || 'en').toLowerCase().replace('_', '-');
        if (ElixirAI.Strings[l]) return l;
        if (l === 'pt-br') return 'pt';
        var base = l.split('-')[0];
        return ElixirAI.Strings[base] ? base : 'en';
    };

    return ElixirAI.Strings;
